package com.ecole.gestion_scolaire.hr.entity; import com.ecole.gestion_scolaire.identity.entity.UserAccount; import jakarta.persistence.*; import java.time.OffsetDateTime; @Entity @Table(name="staff_note") public class StaffNote { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="employee_id") private Employee employee; @Column(nullable=false,length=80) private String category; @Column(nullable=false,columnDefinition="TEXT") private String content; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="created_by") private UserAccount createdBy; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt; @PrePersist void pre(){if(createdAt==null)createdAt=OffsetDateTime.now();} public Long getId(){return id;} public Employee getEmployee(){return employee;} public void setEmployee(Employee v){employee=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public String getContent(){return content;} public void setContent(String v){content=v;} public UserAccount getCreatedBy(){return createdBy;} public void setCreatedBy(UserAccount v){createdBy=v;} public OffsetDateTime getCreatedAt(){return createdAt;} }